      const grup = {}; r.data.rows.filter(x => x.Divisi !== 'LANDING').forEach(x => (grup[x.Divisi] = grup[x.Divisi] || []).push(x));
      isi.innerHTML = `<form id="pp">${Object.keys(grup).map(g => panel('Divisi ' + (g === '*' ? 'Umum (Manager)' : g), `<div class="grid sm:grid-cols-2 gap-3">${grup[g].map(x => `<label class="block"><span class="label">${esc(x.Label || x.Kunci)}</span><input class="input mt-1 font-mono" name="${esc(x.Kunci)}" value="${esc(x.Nilai)}" data-awal="${esc(x.Nilai)}"><span class="font-mono text-[10px] text-secondary">${esc(x.Kunci)}</span></label>`).join('')}</div>`, '', 'mb-3')).join('')}<div class="sticky bottom-16 lg:bottom-0 bg-surface border border-strong p-3 flex justify-end"><button class="tombol tombol-utama">${ik('save')}Simpan perubahan</button></div></form>`;
