      isi.innerHTML = panel('Login Google (Google Identity Services)', `<p class="text-body-sm text-secondary mb-3">Client ID disimpan di Script Properties (bukan di kode/Sheets). Status: ${cid.ada ? badge('Terpasang ' + cid.samar, 'ok') : badge('Belum diisi', 'warn')}</p><form id="ks" class="flex flex-wrap gap-2"><input class="input flex-1 min-w-[260px] font-mono" type="password" autocomplete="off" name="v" placeholder="${cid.ada ? esc(cid.samar) : '1234567890-abc.apps.googleusercontent.com'}"><button class="tombol tombol-utama">${ik('save')}Simpan</button>${cid.ada ? `<button type="button" class="tombol" id="ks-hapus">Hapus</button>` : ''}</form>`) + panel('Akses Darurat', `<p class="text-body-sm">Halaman login darurat: <code class="font-mono">app.html#/masuk/darurat</code> (tidak ditautkan dari mana pun). Sandi awal tampil sekali di log <b>setupAppEnvironment()</b>. Bila lupa, jalankan <b>resetAksesDarurat()</b> dari editor Apps Script. Salah 5× → terkunci 15 menit.</p>`, '', 'mt-3');
      $('#ks').onsubmit = async e => { e.preventDefault(); const v = e.target.v.value.trim(); if (!v) return; const x = await API.api('rahasia.simpan', { kunci: 'GOOGLE_CLIENT_ID', nilai: v }); toast(x.message, x.success ? 'ok' : 'crit'); if (x.success) halPengaturan(main, q); };
