      $('#mg-wadah').innerHTML = panel('Migrasi dari Spreadsheet Lama (sumber hanya DIBACA)', `<form id="mg" class="grid sm:grid-cols-2 gap-3"><label class="sm:col-span-2"><span class="label">URL / ID spreadsheet lama</span><input class="input mt-1 font-mono" name="sumber" required placeholder="https://docs.google.com/spreadsheets/d/…"></label><label><span class="label">Nama sheet</span><input class="input mt-1" name="sheet" required placeholder="Data"></label><label><span class="label">Baris header</span><input class="input mt-1 font-mono" type="number" min="1" name="barisHeader" value="1"></label><label class="sm:col-span-2"><span class="label">Tabel tujuan</span><select class="input mt-1" name="tabel">${B().tabel.map(t => `<option value="${t.key}">${esc((t.master ? 'Master' : t.div) + ' · ' + t.judul)}</option>`).join('')}</select></label><div class="sm:col-span-2 flex gap-2"><button class="tombol" data-m="pindai">${ik('search')}Pindai (dry-run)</button><button class="tombol tombol-utama" data-m="jalankan">${ik('play_arrow')}Jalankan Migrasi</button></div></form><div id="mg-h" class="mt-3"></div><p class="text-body-sm text-secondary mt-3">Kolom dicocokkan berdasarkan <b>nama header</b>. Aman diulang (baris dengan ID sama diperbarui, bukan digandakan). Gunakan akun Google yang sama dengan pemilik spreadsheet lama.</p>`);
      $('#mg').onclick = async e => { const b = e.target.closest('[data-m]'); if (!b) return; e.preventDefault(); const f = new FormData($('#mg')); const d = {}; f.forEach((v, k) => d[k] = v); if (!d.sumber || !d.sheet) return toast('Isi URL dan nama sheet.', 'warn'); if (b.dataset.m === 'jalankan' && !(await konfirmasi('Jalankan migrasi?', 'Data dari spreadsheet lama akan ditambahkan ke tabel tujuan.', { label: 'Jalankan' }))) return; b.disabled = true; const r = await API.api('migrasi.' + b.dataset.m, d); b.disabled = false; $('#mg-h').innerHTML = r.success ? `<pre class="font-mono text-[11px] bg-surface-low border border-hairline p-3 whitespace-pre-wrap">${esc(JSON.stringify(r.data, null, 2))}</pre>` : galat(r.message); if (r.success) toast(r.message || 'Pindai selesai.'); };
